  if (!m) return fail('AMOUNT_INVALID');
  const euros = Number(m[1].replace(/,/g, ''));
  const cents = Number((m[2] ?? '').padEnd(2, '0'));
  return ok(euros * 100 + cents);
}

/**
 * Convert an amount in cents from euros to another currency.
 * @param {number} cents - amount in euro cents
 * @param {string} currency - target currency code (EUR, USD, GBP)
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function convert(cents, currency) {
  if (!RATES[currency]) return fail('UNKNOWN_CURRENCY');

  const euros = cents / 100;
  const converted = euros * RATES[currency];
  const convertedCents = roundCents(converted * 100);

  return ok(convertedCents);
}

/**
 * Format cents as money with currency symbol and proper formatting.
 * @param {number} cents
 * @param {string} currency - EUR, USD, or GBP
 * @returns {string}
 */
export function formatMoney(cents, currency) {
  const symbolMap = {
    EUR: '€',
    USD: '$',
    GBP: '£',
  };

  const symbol = symbolMap[currency];
  if (!symbol) return `Unknown (${currency})`;

  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const amount = Math.floor(abs / 100)
    .toString()
    .replace(/\B(?=(\d{3})+(?!\d))/g, ',');

  return `${sign}${symbol}${amount}.${String(abs % 100).padStart(2, '0')}`;
}

